lab.solution:
def review_lanes(task_ids, lane_count):
    if type(lane_count) is not int or lane_count <= 0:
        raise ValueError('positive integer lane count required')
    groups = {}
    for task_id in task_ids:
        if type(task_id) is not int:
            raise ValueError('integer task ID required')
        groups.setdefault(task_id % lane_count, []).append(task_id)
    return groups

assert review_lanes(list(range(6)), 3) == {0: [0, 3], 1: [1, 4], 2: [2, 5]}
assert review_lanes([-1], 3) == {2: [-1]}
for bad in (0, -2, True):
    try:
        review_lanes([1], bad)
    except ValueError:
        pass
    else:
        raise AssertionError('invalid lane count accepted')
print('lane partition checked')

